   TB(['역할', '발화의 예', '확인할 것'],
      [['~토의 시작', '**배경과 주제**를 제시하며 시작("최근 ~ 문제가 있어 오늘은 ~를 주제로")', '주제 · 필요성 제시'], ['~참여 독려', '"적극적으로 의견을 말씀해 주십시오"', '결과 활용 계획 안내'], ['~발언 기회 분배', '"먼저 ○○ 학생 말씀해 주시고 이어서 ○○ 학생 말씀해 주십시오"', '**순서 지정·조정**'],
       ['~내용 정리', '"지금까지 ~ 세 가지 의견이 나왔습니다"', '발언 요약 · 확인'], ['~개념 확인', '"~란 무엇인가요?"', '용어 의미 질문'], ['~시간 관리', '"20분 동안 진행하겠습니다"', '시간 안내']], left=(1, 2)),
